from typing import List

def isWordExist(board: List[List[str]], word: str) -> bool:
    def dfs(x, y, index):
        if index == len(word):
            return True
        if x < 0 or x >= len(board) or y < 0 or y >= len(board[0]) or board[x][y] != word[index]:
            return False

        temp, board[x][y] = board[x][y], '#'
        found = (dfs(x + 1, y, index + 1) or
                dfs(x - 1, y, index + 1) or
                dfs(x, y + 1, index + 1) or
                dfs(x, y - 1, index + 1))
        board[x][y] = temp

        return found

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == word[0] and dfs(i, j, 0):
                return True

    return False
